{"command":"python3 << 'PY'
import json

with open("/workspace/raw.json") as f:
    raw = json.load(f)

DRIVERS = [
    "NOR","PIA","RUS","ANT","VER","HAD","LEC","HAM",
    "ALB","SAI","LIN","LAW","STR","ALO","OCO","BEA",
    "HUL","BOR","GAS","COL","PER","BOT",
]
SCALE = 10**6

def to_int_parts(probs, total):
    xs = [p * total for p in probs]
    floors = [int(x) for x in xs]
    rem = total - sum(floors)
    order = sorted(range(len(xs)), key=lambda i: (xs[i] - floors[i], -i), reverse=True)
    for j in range(rem):
        floors[order[j]] += 1
    return floors

table_pos = {}
meta = {}
for d in DRIVERS:
    r = raw["results"][d]
    vec = r["positions"] + [r["nc"], r["dns"], r["dsq"]]
    parts = to_int_parts(vec, SCALE)
    table_pos[d] = parts[:22]
    meta[d] = dict(nc=parts[22], dns=parts[23], dsq=parts[24],
                   ret=max(0, min(SCALE, int(round(r["retirement"] * SCALE)))))

def occ(k):
    return sum(table_pos[d][k] for d in DRIVERS)

# Make occupancy non-increasing by promoting mass from later to earlier positions
# occ[k] should be >= occ[k+1]
changed = True
guard = 0
while changed and guard < 50000:
    changed = False
    guard += 1
    for k in range(21):
        while occ(k+1) > occ(k):
            # move 1 unit of some driver from k+1 to k
            d = max(DRIVERS, key=lambda x: table_pos[x][k+1])
            if table_pos[d][k+1] <= 0:
                # try any driver
                found = False
                for x in DRIVERS:
                    if table_pos[x][k+1] > 0:
                        d = x; found=True; break
                if not found:
                    break
            table_pos[d][k+1] -= 1
            table_pos[d][k] += 1
            changed = True

# Cap columns at SCALE by moving excess to nc
for k in range(22):
    while occ(k) > SCALE:
        d = max(DRIVERS, key=lambda x: table_pos[x][k])
        table_pos[d][k] -= 1
        meta[d]["nc"] += 1

# After capping, re-enforce monotone (cap can break it only if we cap earlier more, unlikely)
changed = True
guard = 0
while changed and guard < 20000:
    changed = False
    guard += 1
    for k in range(21):
        if occ(k+1) > occ(k):
            d = max(DRIVERS, key=lambda x: table_pos[x][k+1])
            if table_pos[d][k+1] > 0:
                table_pos[d][k+1] -= 1
                table_pos[d][k] += 1
                changed = True

# Driver sums
for d in DRIVERS:
    s = sum(table_pos[d]) + meta[d]["nc"] + meta[d]["dns"] + meta[d]["dsq"]
    if s != SCALE:
        meta[d]["nc"] += SCALE - s
        if meta[d]["nc"] < 0:
            need = -meta[d]["nc"]
            meta[d]["nc"] = 0
            for k in range(21, -1, -1):
                take = min(need, table_pos[d][k])
                table_pos[d][k] -= take
                need -= take
                if need == 0:
                    break

def f(n):
    return n / SCALE

ok = True
issues = []
for d in DRIVERS:
    s = sum(table_pos[d]) + meta[d]["nc"] + meta[d]["dns"] + meta[d]["dsq"]
    if s != SCALE:
        issues.append(("sum", d, s)); ok=False
    for name, val in list(enumerate(table_pos[d])) + [("nc", meta[d]["nc"]), ("dns", meta[d]["dns"]), ("dsq", meta[d]["dsq"]), ("ret", meta[d]["ret"])]:
        v = val if isinstance(name, str) else table_pos[d][name]
        if not (0 <= v <= SCALE):
            issues.append(("range", d, name, v)); ok=False
occs = [occ(k) for k in range(22)]
for k in range(22):
    if occs[k] > SCALE:
        issues.append(("col", k, occs[k])); ok=False
for k in range(21):
    if occs[k+1] > occs[k]:
        issues.append(("mono", k, occs[k], occs[k+1])); ok=False

print("ok", ok, "issues", issues[:10], "n", len(issues))
print("occ", occs)
print("P1", occs[0], "Eclass", sum(occs)/SCALE)

pred = {"event_id": "2026-15-azerbaijan", "drivers": {}}
for d in DRIVERS:
    pred["drivers"][d] = {
        "positions": [f(x) for x in table_pos[d]],
        "nc": f(meta[d]["nc"]),
        "dns": f(meta[d]["dns"]),
        "dsq": f(meta[d]["dsq"]),
        "retirement": f(meta[d]["ret"]),
    }

# JSON dump with 6 decimals as numbers (not strings)
class F(float):
    pass

with open("/output/prediction.json","w") as fp:
    json.dump(pred, fp, indent=2)

# re-validate from file
with open("/output/prediction.json") as fp:
    P = json.load(fp)
print("\nfile validation")
for d in DRIVERS:
    dd = P["drivers"][d]
    s = sum(dd["positions"]) + dd["nc"] + dd["dns"] + dd["dsq"]
    if abs(s-1) > 1e-9:
        print("file sum", d, s)
occsf = [sum(P["drivers"][d]["positions"][k] for d in DRIVERS) for k in range(22)]
print("file occ", occsf)
print("file mono", all(occsf[k]+1e-12 >= occsf[k+1] for k in range(21)))
print("file maxcol", max(occsf))
print("wins", {d: P["drivers"][d]["positions"][0] for d in ["RUS","PIA","LEC","ANT","VER","HAD","NOR","HAM"]})
print("win sum", sum(P["drivers"][d]["positions"][0] for d in DRIVERS))
